-- V16__seed_548_curated_activities.sql
-- Add V2 schema columns to activities table and seed 548 authentic curated activities

-- 1. Add V2 columns to activities table
ALTER TABLE activities ADD COLUMN IF NOT EXISTS source VARCHAR(30) NOT NULL DEFAULT 'CURATED';
ALTER TABLE activities ADD COLUMN IF NOT EXISTS external_id VARCHAR(255);
ALTER TABLE activities ADD COLUMN IF NOT EXISTS latitude NUMERIC(10, 7);
ALTER TABLE activities ADD COLUMN IF NOT EXISTS longitude NUMERIC(10, 7);

CREATE INDEX IF NOT EXISTS idx_activities_source ON activities(source);

-- 2. Mark existing V1 activities as LEGACY
UPDATE activities SET source = 'LEGACY' WHERE source IS NULL OR source = 'CURATED';

-- 3. Seed 548 Authentic Curated Activities across 137 Curated Destinations

-- 4. Reset activities sequence
SELECT setval('activities_id_seq', (SELECT MAX(id) FROM activities));